package ir.matab.desk;
import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.time.*;
import java.util.*;
final class HistorySupport{
 static final String[] ACTIONS={"add","update","delete","restore","export","migrate","install"};
 static final String[] TYPES={"service","payment","material_receipt","material_use","customer","doctor","service_type","product","area","payment_method","settings","appearance","application","backup"};
 static String meta(SQLiteDatabase db,String key){try(Cursor c=db.rawQuery("SELECT value FROM meta WHERE key=?",new String[]{key})){return c.moveToFirst()?c.getString(0):null;}}
 static void initialize(SQLiteDatabase db,Context context)throws Exception{
  db.execSQL("CREATE TABLE IF NOT EXISTS activity_log(id INTEGER PRIMARY KEY AUTOINCREMENT,occurred_at TEXT NOT NULL,local_day TEXT NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,label TEXT NOT NULL,details_json TEXT NOT NULL,imported INTEGER NOT NULL DEFAULT 0,source_key TEXT UNIQUE)");
  db.execSQL("CREATE INDEX IF NOT EXISTS idx_log_day ON activity_log(local_day,id)");db.execSQL("CREATE INDEX IF NOT EXISTS idx_log_action ON activity_log(action,entity_type,id)");db.execSQL("CREATE TABLE IF NOT EXISTS app_releases(version_code INTEGER PRIMARY KEY,version_name TEXT NOT NULL,release_date TEXT NOT NULL,changes_json TEXT NOT NULL)");
  if(meta(db,"instanceId")==null)db.execSQL("INSERT INTO meta VALUES(?,?)",new Object[]{"instanceId",UUID.randomUUID().toString()});
  JSONObject packageInfo=new JSONObject(LocalDatabase.readAsset(context,"releases.json"));JSONArray releases=packageInfo.getJSONArray("releases");for(int i=0;i<releases.length();i++){JSONObject r=releases.getJSONObject(i);db.execSQL("INSERT OR IGNORE INTO app_releases VALUES(?,?,?,?)",new Object[]{r.getInt("versionCode"),r.getString("versionName"),r.getString("date"),r.getJSONArray("changes").toString()});}
  String current=""+packageInfo.getJSONObject("current").getInt("versionCode");if(!current.equals(meta(db,"installedVersionCode"))){boolean installed=meta(db,"clinic")!=null;add(db,installed?"update":"install","application","نسخه "+packageInfo.getJSONObject("current").getString("versionName"),"",new JSONObject().put("version",packageInfo.getJSONObject("current").getString("versionName")),null,false,null);db.execSQL("INSERT OR REPLACE INTO meta VALUES(?,?)",new Object[]{"installedVersionCode",current});}
 }
 static void add(SQLiteDatabase db,String action,String kind,String label,String id,JSONObject details,String timestamp,boolean imported,String source)throws Exception{add(db,action,kind,label,id,details,timestamp,imported,source,null);}
 static void add(SQLiteDatabase db,String action,String kind,String label,String id,JSONObject details,String timestamp,boolean imported,String source,String clinicId)throws Exception{
  String stamp=timestamp==null?Instant.now().toString():timestamp,day=OffsetDateTime.parse(stamp).atZoneSameInstant(ZoneId.of("Asia/Tehran")).toLocalDate().toString();if(source==null)source=meta(db,"instanceId")+":"+UUID.randomUUID();
  String columns="occurred_at,local_day,action,entity_type,entity_id,label,details_json,imported,source_key",marks="?,?,?,?,?,?,?,?,?";List<Object> values=new ArrayList<>(Arrays.asList(stamp,day,action,kind,id,label.length()>320?label.substring(0,320):label,details.toString(),imported?1:0,source));if(clinicId!=null){columns+=",clinic_id";marks+=",?";values.add(clinicId);}db.execSQL("INSERT OR IGNORE INTO activity_log("+columns+") VALUES("+marks+")",values.toArray());
 }
 static JSONObject releaseHistory(SQLiteDatabase db,Context context)throws Exception{
  JSONArray rows=new JSONArray();try(Cursor c=db.rawQuery("SELECT * FROM app_releases ORDER BY version_code DESC",null)){while(c.moveToNext())rows.put(new JSONObject().put("versionCode",c.getInt(0)).put("versionName",c.getString(1)).put("date",c.getString(2)).put("changes",new JSONArray(c.getString(3))));}return new JSONObject().put("current",new JSONObject(LocalDatabase.readAsset(context,"releases.json")).getJSONObject("current")).put("releases",rows);
 }
 static JSONObject history(SQLiteDatabase db,JSONObject f,boolean all)throws Exception{return history(db,f,all,null);}
 static JSONObject history(SQLiteDatabase db,JSONObject f,boolean all,String clinicId)throws Exception{
  List<String> clauses=new ArrayList<>(),args=new ArrayList<>();if(clinicId!=null){clauses.add("(clinic_id=? OR clinic_id='*')");args.add(clinicId);}String action=f.optString("action",""),type=f.optString("entityType","");if(!action.isEmpty()){if(!Arrays.asList(ACTIONS).contains(action))throw new Exception("فیلتر معتبر نیست.");clauses.add("action=?");args.add(action);}if(!type.isEmpty()){if(!Arrays.asList(TYPES).contains(type))throw new Exception("فیلتر معتبر نیست.");clauses.add("entity_type=?");args.add(type);}for(String key:new String[]{"from","to"}){String value=f.optString(key,"");if(!value.isEmpty()){LocalDate.parse(value);String op=key.equals("from")?">=":"<=";clauses.add("local_day"+op+"?");args.add(value);String clock=f.optString(key+"Time","");if(!clock.isEmpty()){if(!clock.matches("[0-2][0-9]:[0-5][0-9]"))throw new Exception("ساعت معتبر نیست.");LocalTime time=LocalTime.parse(clock);if(key.equals("to"))time=time.withSecond(59).withNano(999000000);String point=ZonedDateTime.of(LocalDate.parse(value),time,ZoneId.of("Asia/Tehran")).toInstant().toString();clauses.add("julianday(occurred_at)"+op+"julianday(?)");args.add(point);}}else if(!f.optString(key+"Time","").isEmpty())throw new Exception("برای ساعت، تاریخ لازم است.");}
  String q=f.optString("q","");if(!q.isEmpty()){clauses.add("(label LIKE ? OR entity_id LIKE ?)");args.add("%"+q+"%");args.add("%"+q+"%");}String where=clauses.isEmpty()?"":" WHERE "+String.join(" AND ",clauses);long total;try(Cursor c=db.rawQuery("SELECT count(*) FROM activity_log"+where,args.toArray(new String[0]))){c.moveToFirst();total=c.getLong(0);}String sql="SELECT * FROM activity_log"+where+" ORDER BY id DESC";if(!all){sql+=" LIMIT ? OFFSET ?";args.add(""+Math.max(1,Math.min(100,f.optInt("limit",50))));args.add(""+Math.max(0,f.optInt("offset",0)));}
  JSONArray rows=new JSONArray();try(Cursor c=db.rawQuery(sql,args.toArray(new String[0]))){while(c.moveToNext())rows.put(new JSONObject().put("id",c.getLong(0)).put("timestamp",c.getString(1)).put("action",c.getString(3)).put("entityType",c.getString(4)).put("entityId",c.getString(5)).put("label",c.getString(6)).put("details",new JSONObject(c.getString(7))).put("imported",c.getInt(8)==1).put("sourceKey",c.getString(9)));}return new JSONObject().put("total",total).put("rows",rows);
 }
 static void validateHistory(JSONArray rows)throws Exception{if(rows==null)return;if(rows.length()>100000)throw new Exception("تاریخچه پشتیبان معتبر نیست.");for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(!Arrays.asList(ACTIONS).contains(r.getString("action"))||!Arrays.asList(TYPES).contains(r.getString("entityType")))throw new Exception("تاریخچه پشتیبان معتبر نیست.");ProfileValidator.text(r,"timestamp",40);OffsetDateTime.parse(r.getString("timestamp"));ProfileValidator.text(r,"entityId",250);ProfileValidator.text(r,"label",320);ProfileValidator.text(r,"sourceKey",200);if(r.getJSONObject("details").toString().length()>2*1024*1024)throw new Exception("تاریخچه پشتیبان معتبر نیست.");}}
 static void importRows(SQLiteDatabase db,JSONArray rows)throws Exception{importRows(db,rows,null);}
 static void importRows(SQLiteDatabase db,JSONArray rows,String clinicId)throws Exception{if(rows==null)return;for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);add(db,r.getString("action"),r.getString("entityType"),r.getString("label"),r.getString("entityId"),r.getJSONObject("details"),r.getString("timestamp"),true,r.getString("sourceKey"),clinicId);}}
 static boolean equal(Object a,Object b)throws Exception{
  if(a==JSONObject.NULL)a=null;if(b==JSONObject.NULL)b=null;if(a==null||b==null)return a==b;
  if(a instanceof Number&&b instanceof Number)return ((Number)a).doubleValue()==((Number)b).doubleValue();
  if(a instanceof JSONObject&&b instanceof JSONObject){JSONObject x=(JSONObject)a,y=(JSONObject)b;if(x.length()!=y.length())return false;Iterator<String> keys=x.keys();while(keys.hasNext()){String key=keys.next();if(!y.has(key)||!equal(x.get(key),y.get(key)))return false;}return true;}
  if(a instanceof JSONArray&&b instanceof JSONArray){JSONArray x=(JSONArray)a,y=(JSONArray)b;if(x.length()!=y.length())return false;for(int i=0;i<x.length();i++)if(!equal(x.get(i),y.get(i)))return false;return true;}
  return a.equals(b);
 }
 static final class Item{String kind,id,label;JSONObject row;Item(String k,String id,String l,JSONObject r){kind=k;this.id=id;label=l;row=r;}}
 static void put(Map<String,Item> out,String k,String id,String label,JSONObject r){out.put(k+"|"+id,new Item(k,id,label,r));}
 static Map<String,Item> collections(JSONObject s)throws Exception{
  Map<String,Item> out=new LinkedHashMap<>();JSONArray ps=s.getJSONArray("patients");for(int i=0;i<ps.length();i++){JSONObject p=ps.getJSONObject(i);put(out,"customer",p.getString("id"),ProfileValidator.name(p),p);}
  JSONObject cats=s.getJSONObject("catalogs");for(String[] pair:new String[][]{{"services","service_type"},{"products","product"},{"areas","area"},{"methods","payment_method"},{"doctors","doctor"}}){JSONArray entries=cats.getJSONArray(pair[0]);for(int i=0;i<entries.length();i++){JSONObject c=entries.getJSONObject(i);put(out,pair[1],c.getString("id"),c.getString("name"),c);}}
  JSONArray rs=s.getJSONArray("records");for(int i=0;i<rs.length();i++){JSONObject r=rs.getJSONObject(i);String id=r.getString("id"),service=r.getString("service");put(out,"service",id,service+" · "+r.getString("patient"),r);JSONArray payments=r.getJSONArray("payments");for(int j=0;j<payments.length();j++){JSONObject p=payments.getJSONObject(j);put(out,"payment",id+"/"+p.getString("id"),p.getString("methodLabel")+" · "+service,p);}JSONArray uses=r.getJSONArray("consumptions");for(int j=0;j<uses.length();j++){JSONObject c=uses.getJSONObject(j);put(out,"material_use",id+"/"+c.getString("id"),"مصرف ماده · "+service,c);}}
  JSONArray receipts=s.getJSONArray("receipts");for(int i=0;i<receipts.length();i++){JSONObject r=receipts.getJSONObject(i);put(out,"material_receipt",r.getString("id"),r.getString("productLabel"),r);}return out;
 }
 static void emit(SQLiteDatabase db,String clinicId,String action,String kind,String label,String id,JSONObject details,String stamp,boolean imported,String source)throws Exception{String scope=clinicId;if(scope!=null&&Arrays.asList("service_type","product","area","payment_method").contains(kind))scope="*";add(db,action,kind,label,id,details,stamp,imported,source,scope);}
 static void changes(SQLiteDatabase db,JSONObject old,JSONObject next,String operation)throws Exception{changes(db,old,next,operation,null);}
 static void changes(SQLiteDatabase db,JSONObject old,JSONObject next,String operation,String clinicId)throws Exception{
  if(operation.equals("restore")||operation.equals("restore-settings")){emit(db,clinicId,"restore","backup",operation.equals("restore")?"بازیابی بانک کامل":"بازیابی تنظیمات","",new JSONObject().put("services",next.getJSONArray("records").length()).put("receipts",next.getJSONArray("receipts").length()),null,false,null);return;}
  if(old==null){emit(db,clinicId,"add","settings","ایجاد بانک اطلاعات","",new JSONObject(),null,false,null);return;}
  if(old.optInt("version")<5){emit(db,clinicId,"migrate","application","به‌روزرسانی ساختار اطلاعات با حفظ سوابق","",new JSONObject(),null,false,null);return;}
  Map<String,Item> a=collections(old),b=collections(next);Set<String> keys=new LinkedHashSet<>();keys.addAll(a.keySet());keys.addAll(b.keySet());for(String key:keys){Item x=a.get(key),y=b.get(key);if(x!=null&&y!=null&&equal(x.row,y.row))continue;Item item=y==null?x:y;Set<String> fields=new LinkedHashSet<>();if(x!=null){Iterator<String> it=x.row.keys();while(it.hasNext())fields.add(it.next());}if(y!=null){Iterator<String> it=y.row.keys();while(it.hasNext())fields.add(it.next());}JSONArray changed=new JSONArray();for(String field:fields)if(!equal(x==null?null:x.row.opt(field),y==null?null:y.row.opt(field)))changed.put(field);emit(db,clinicId,x!=null&&y!=null?"update":y!=null?"add":"delete",item.kind,item.label,item.id,new JSONObject().put("fields",changed).put("before",x==null?JSONObject.NULL:x.row).put("after",y==null?JSONObject.NULL:y.row),null,false,null);}
  if(!old.getString("clinic").equals(next.getString("clinic")))emit(db,clinicId,"update","settings","تغییر نام مطب","",new JSONObject().put("fields",new JSONArray().put("clinic")).put("before",new JSONObject().put("clinic",old.getString("clinic"))).put("after",new JSONObject().put("clinic",next.getString("clinic"))),null,false,null);
  if(!equal(old.getJSONObject("settings"),next.getJSONObject("settings"))){JSONObject x=old.getJSONObject("settings"),y=next.getJSONObject("settings");boolean appearanceOnly=equal(x.opt("appearance"),y.opt("appearance"))?false:true;JSONObject xx=new JSONObject(x.toString()),yy=new JSONObject(y.toString());xx.remove("appearance");yy.remove("appearance");appearanceOnly=appearanceOnly&&equal(xx,yy);emit(db,clinicId,"update",appearanceOnly?"appearance":"settings","تغییر تنظیمات برنامه","",new JSONObject().put("fields",new JSONArray().put(appearanceOnly?"appearance":"settings")).put("before",x).put("after",y),null,false,null);}
 }
}
